  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // i_slverr_en enables error responses. When disabled, PSTRB still selects the bytes written.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en & (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite));

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Capture PSTRB independently of i_slverr_en; it always masks the bytes updated by a write.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign w_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_aesgcm_ctrl = w_wr_en & (reg_addr == LPARA_AESGCM_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_cfg = w_wr_en & (reg_addr == LPARA_AESGCM_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_aadlen = w_wr_en & (reg_addr == LPARA_AESGCM_AADLEN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_datalen = w_wr_en & (reg_addr == LPARA_AESGCM_DATALEN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_keywait = w_wr_en & (reg_addr == LPARA_AESGCM_KEYWAIT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_0 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_1 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_2 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_2_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_3 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_3_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_4 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_4_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_5 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_5_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_6 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_6_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_key_7 = w_wr_en & (reg_addr == LPARA_AESGCM_KEY_7_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_iv_0 = w_wr_en & (reg_addr == LPARA_AESGCM_IV_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_iv_1 = w_wr_en & (reg_addr == LPARA_AESGCM_IV_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_iv_2 = w_wr_en & (reg_addr == LPARA_AESGCM_IV_2_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_iv_3 = w_wr_en & (reg_addr == LPARA_AESGCM_IV_3_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_tagin_0 = w_wr_en & (reg_addr == LPARA_AESGCM_TAGIN_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_tagin_1 = w_wr_en & (reg_addr == LPARA_AESGCM_TAGIN_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_tagin_2 = w_wr_en & (reg_addr == LPARA_AESGCM_TAGIN_2_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_tagin_3 = w_wr_en & (reg_addr == LPARA_AESGCM_TAGIN_3_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_irq_raw = w_wr_en & (reg_addr == LPARA_AESGCM_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_irq_en = w_wr_en & (reg_addr == LPARA_AESGCM_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_irq_inj = w_wr_en & (reg_addr == LPARA_AESGCM_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_dmacfg = w_wr_en & (reg_addr == LPARA_AESGCM_DMACFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_pio_din = w_wr_en & (reg_addr == LPARA_AESGCM_PIO_DIN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_0 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_1 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_2 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_2_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_3 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_3_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_4 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_4_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_5 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_5_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_6 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_6_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_7 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_7_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_8 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_8_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_9 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_9_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_10 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_10_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_11 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_11_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_12 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_12_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_13 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_13_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_14 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_14_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_15 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_15_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_16 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_16_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_17 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_17_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_18 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_18_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_19 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_19_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_20 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_20_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_21 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_21_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_22 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_22_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_aesgcm_ctxx_23 = w_wr_en & (reg_addr == LPARA_AESGCM_CTXX_23_OFFSET[LPARA_ADDR_W-1:0]);

  // Register transaction events are qualified by the captured APB transfer.
  // Read events include aligned unmapped reads, which return zero. Unaligned reads
  // are suppressed even when the APB error response is disabled.
  assign o_reg_rd_en   = w_rd_en & (reg_addr[1:0] == 2'b0);
  assign o_reg_rd_addr = o_reg_rd_en ? reg_addr : '0;

  // Write events are asserted only for a mapped register with at least one
  // software-writable field; rejected and read-only writes do not assert this event.
  assign o_reg_wr_en   =
    (|w_we_aesgcm_ctrl)
    | (|w_we_aesgcm_cfg)
    | (|w_we_aesgcm_aadlen)
    | (|w_we_aesgcm_datalen)
    | (|w_we_aesgcm_keywait)
    | (|w_we_aesgcm_key_0)
    | (|w_we_aesgcm_key_1)
    | (|w_we_aesgcm_key_2)
    | (|w_we_aesgcm_key_3)
    | (|w_we_aesgcm_key_4)
    | (|w_we_aesgcm_key_5)
    | (|w_we_aesgcm_key_6)
    | (|w_we_aesgcm_key_7)
    | (|w_we_aesgcm_iv_0)
    | (|w_we_aesgcm_iv_1)
    | (|w_we_aesgcm_iv_2)
    | (|w_we_aesgcm_iv_3)
    | (|w_we_aesgcm_tagin_0)
    | (|w_we_aesgcm_tagin_1)
    | (|w_we_aesgcm_tagin_2)
    | (|w_we_aesgcm_tagin_3)
    | (|w_we_aesgcm_irq_raw)
    | (|w_we_aesgcm_irq_en)
    | (|w_we_aesgcm_irq_inj)
    | (|w_we_aesgcm_dmacfg)
    | (|w_we_aesgcm_pio_din)
    | (|w_we_aesgcm_ctxx_0)
    | (|w_we_aesgcm_ctxx_1)
    | (|w_we_aesgcm_ctxx_2)
    | (|w_we_aesgcm_ctxx_3)
    | (|w_we_aesgcm_ctxx_4)
    | (|w_we_aesgcm_ctxx_5)
    | (|w_we_aesgcm_ctxx_6)
    | (|w_we_aesgcm_ctxx_7)
    | (|w_we_aesgcm_ctxx_8)
    | (|w_we_aesgcm_ctxx_9)
    | (|w_we_aesgcm_ctxx_10)
    | (|w_we_aesgcm_ctxx_11)
    | (|w_we_aesgcm_ctxx_12)
    | (|w_we_aesgcm_ctxx_13)
    | (|w_we_aesgcm_ctxx_14)
    | (|w_we_aesgcm_ctxx_15)
    | (|w_we_aesgcm_ctxx_16)
    | (|w_we_aesgcm_ctxx_17)
    | (|w_we_aesgcm_ctxx_18)
    | (|w_we_aesgcm_ctxx_19)
    | (|w_we_aesgcm_ctxx_20)
    | (|w_we_aesgcm_ctxx_21)
    | (|w_we_aesgcm_ctxx_22)
    | (|w_we_aesgcm_ctxx_23);
  assign o_reg_wr_addr = o_reg_wr_en ? reg_addr : '0;

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

      // PREADY pulses after an acknowledged operation or a SETUP-phase error.
      assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end else begin : g_sync_csr

      // Synchronous-only request capture and response state.
      logic reg_rd_capture;
      logic reg_wr_capture;
      logic w_pready_nxt;
      logic reg_pready;

      // Read/write enables are delayed one cycle in synchronous mode.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
        if (!i_rst_n_apb) begin
          reg_rd_capture <= 1'b0;
          reg_wr_capture <= 1'b0;
        end else begin
          reg_rd_capture <= w_apb_rd;
          reg_wr_capture <= w_apb_wr;
        end
      end
      assign w_rd_en = reg_rd_capture;
      assign w_wr_en = reg_wr_capture;
      assign w_rd_ack_fall = 1'b0;

      // PREADY pulses after an operation or a SETUP-phase error.
      assign w_pready_nxt = w_wr_en | w_rd_en | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end
  endgenerate

  // Register aesgcm_version: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_aesgcm_version_value
    w_aesgcm_version_value = '0;
    w_aesgcm_version_value[31:16] = i_aesgcm_version_major;
    w_aesgcm_version_value[15:0] = i_aesgcm_version_minor;
  end

  // Register aesgcm_cap: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_aesgcm_cap_value
    w_aesgcm_cap_value = '0;
    w_aesgcm_cap_value[21:20] = i_aesgcm_cap_axi_dw;
    w_aesgcm_cap_value[17:16] = i_aesgcm_cap_ghash;
    w_aesgcm_cap_value[14:12] = i_aesgcm_cap_lanes;
    w_aesgcm_cap_value[10:8] = i_aesgcm_cap_ctx_num;
    w_aesgcm_cap_value[6] = i_aesgcm_cap_ctx_exp;
    w_aesgcm_cap_value[5:4] = i_aesgcm_cap_policy;
    w_aesgcm_cap_value[3] = i_aesgcm_cap_async;
    w_aesgcm_cap_value[2] = i_aesgcm_cap_key_side;
    w_aesgcm_cap_value[1] = i_aesgcm_cap_axi_en;
    w_aesgcm_cap_value[0] = i_aesgcm_cap_gcm_en;
  end

  // aesgcm_ctrl_en next value (rw): update only byte lanes selected by the bus strobe.
  assign w_aesgcm_ctrl_en_nxt = (w_we_aesgcm_ctrl & (|w_wmask[8])) ? ((reg_wdata[8] & w_wmask[8]) | (reg_aesgcm_ctrl_en & ~w_wmask[8])) : reg_aesgcm_ctrl_en;

  // aesgcm_ctrl_free next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_free_nxt = (i_hw_we_aesgcm_ctrl_free) ? i_hw_wdata_aesgcm_ctrl_free
                          : ((w_we_aesgcm_ctrl & (|w_wmask[6])) ? ((reg_wdata[6] & w_wmask[6]) | (reg_aesgcm_ctrl_free & ~w_wmask[6])) : reg_aesgcm_ctrl_free);

  // aesgcm_ctrl_key_new next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_key_new_nxt = (i_hw_we_aesgcm_ctrl_key_new) ? i_hw_wdata_aesgcm_ctrl_key_new
                          : ((w_we_aesgcm_ctrl & (|w_wmask[5])) ? ((reg_wdata[5] & w_wmask[5]) | (reg_aesgcm_ctrl_key_new & ~w_wmask[5])) : reg_aesgcm_ctrl_key_new);

  // aesgcm_ctrl_resume next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_resume_nxt = (i_hw_we_aesgcm_ctrl_resume) ? i_hw_wdata_aesgcm_ctrl_resume
                          : ((w_we_aesgcm_ctrl & (|w_wmask[4])) ? ((reg_wdata[4] & w_wmask[4]) | (reg_aesgcm_ctrl_resume & ~w_wmask[4])) : reg_aesgcm_ctrl_resume);

  // aesgcm_ctrl_suspend next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_suspend_nxt = (i_hw_we_aesgcm_ctrl_suspend) ? i_hw_wdata_aesgcm_ctrl_suspend
                          : ((w_we_aesgcm_ctrl & (|w_wmask[3])) ? ((reg_wdata[3] & w_wmask[3]) | (reg_aesgcm_ctrl_suspend & ~w_wmask[3])) : reg_aesgcm_ctrl_suspend);

  // aesgcm_ctrl_zeroize next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_zeroize_nxt = (i_hw_we_aesgcm_ctrl_zeroize) ? i_hw_wdata_aesgcm_ctrl_zeroize
                          : ((w_we_aesgcm_ctrl & (|w_wmask[2])) ? ((reg_wdata[2] & w_wmask[2]) | (reg_aesgcm_ctrl_zeroize & ~w_wmask[2])) : reg_aesgcm_ctrl_zeroize);

  // aesgcm_ctrl_abort next value (rwi): hardware load wins; otherwise selected written bits load.
  assign w_aesgcm_ctrl_abort_nxt = (i_hw_we_aesgcm_ctrl_abort) ? i_hw_wdata_aesgcm_ctrl_abort
